prompt.output_format:
    Return ONLY valid JSON. No markdown, no text before or after.

{
  "photo_quality": "good | fair | poor, with a short reason",
  "site_type": {"value": "one of site_type_options", "confidence": "low | medium | high"},
  "recommended_mode": {"value": "repair | new_construction | unclear", "confidence": "low | medium | high", "reason": "short, based on what is visible"},
  "new_road_notes": {"terrain": "flat | sloping | uneven | not visible", "drainage_concerns": "short", "obstacles": "trees, poles, structures, water body, or none visible", "cc_vs_bt_factors": "neutral factors only, no decision"},
  "road_type": {"value": "one of road_type_options", "confidence": "low | medium | high"},
  "surface_condition": "one or two plain sentences",
  "defects": [
    {"type": "from defect_options", "severity": "minor | moderate | severe", "confidence": "low | medium | high", "note": "short"}
  ],
  "suggested_works": [
    {
      "work": "short name, e.g. Pothole patching",
      "reason": "why, based on what is visible",
      "suggested_chapters": ["chapter names from allowed_ssr_chapters only"],
      "search_keywords": ["2 to 5 keywords to search SSR item descriptions"],
      "confidence": "low | medium | high"
    }
  ],
  "suggested_parameters": [
    {"name": "parameter name", "why_needed": "short"}
  ],
  "limitations": "what could not be judged from this photo"
}
